# /videos/ and /thumbnails/ to MinIO (signature host validation, no rewrite).

server {
    listen 80;

    # Multipart upload limit (must match MAX_UPLOAD_SIZE in the app).
    client_max_body_size 512m;

    location /videos/ {
        proxy_pass http://minio:9000;
        proxy_set_header Host $host;
        proxy_request_buffering off;
    }

    location /thumbnails/ {
        proxy_pass http://minio:9000;
        proxy_set_header Host $host;
    }

    location /media/thumbnails/ {
        # Public-read bucket: rewrite /media/thumbnails/<obj> -> /thumbnails/<obj>
        rewrite ^/media/thumbnails/(.*)$ /thumbnails/$1 break;
        proxy_pass http://minio:9000;
        proxy_set_header Host $host;
    }

    location / {
        proxy_pass http://web:8000;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
    }
}
