def _thumb_url(video) -> str | None:
    key = getattr(video, "thumbnail_key", None)
    if not key:
        return None
    if getattr(video, "is_private", False):
        return None  # private thumbs are presigned at page render (stage 3 UI)
    return f"/media/{key}"


