                    "password": "Password123",
                    "channel_name": "Channel Three",
                },
                headers={"Origin": "http://203.0.113.10"},
            )
            assert resp.status_code == 201

    def test_no_origin_non_browser_passes(self, monkeypatch: pytest.MonkeyPatchself -> None:
        with _make_client(monkeypatch, ) as client:
            resp = client.post(
                "/auth/register",
                json={
                    "email": "user4@example.com",
                    "password": "Password123",
                    "channel_name": "Channel Four",
                },
            )
            assert resp.status_code == 201

    def test_origin_null_rejected(self, monkeypatch: pytest.MonkeyPatchself -> None:
        with _make_client(monkeypatch, ) as client:
            resp = client.post(
                "/auth/register",
                json={
                    "email": "user5@example.com",
                    "password": "Password123",
                    "channel_name": "Channel Five",
                },
                headers={"Origin": "null"},
            )
            assert resp.status_code == 403

    def test_referer_without_origin_checked_the_same(self, monkeypatch: pytest.MonkeyPatchself -> None:
        with _make_client(monkeypatch, ) as client:
            resp = client.post(
                "/auth/register",
                json={
                    "email": "user6@example.com",
                    "password": "Password123",
                    "channel_name": "Channel Six",
                },
                headers={"Referer": "http://evil.example/attack"},
            )
